    g_log[0] = 0;
    Script b = { 1, 0, -1, 0, 0 };
    b.Main();
    ok = ok && !std::strcmp(g_log, "GuildTrainingHSP;post;guards_off;") && b.Bindings == 14 && b.Frames == 5;
    g_log[0] = 0;
    Script c = { 0, 0, 3, 0, 0 };
